insert into public.tipos_laudo (id, codigo, nome, descricao, ordem, ativo) values
  ('68f7de95-a821-5f2a-ad5f-f88a0108eb77', 'deficiencia', 'Deficiência / Funcionalidade', 'Avaliação médico-pericial da deficiência e funcionalidade (modelo biopsicossocial/CIF): impedimento, duração, funções e estruturas do corpo, atividades e participação, atividades de vida diária, fatores ambientais (barreiras/facilitadores), tecnologias assistivas, repercussão funcional global e prognóstico. Um único módulo com dois documentos de saída, definidos pelo campo ''Modo do documento'': Relatório médico-pericial (perícia) ou Parecer técnico (assistência técnica, com contexto do solicitante, documentos analisados, análise ponto a ponto e confronto com a prova existente). O sistema não equipara diagnóstico, deficiência, incapacidade laboral e incapacidade civil.', 9, true);
